export const appScript = "import { buildDiagnosisReport } from '/diagnosis-model.js';\n\nconst state={company:{name:'美的集团',thscode:'000333.SZ',companyType:'manufacturing'},question:'增长放缓是否伴随经营质量下降？',bundle:null,report:null};\nconst $=id=>document.getElementById(id);\nconst esc=value=>String(value??'').replace(/[&<>'\"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[char]));\nconst directionLabels={positive:'正面',negative:'负面',conflicting:'矛盾',missing:'缺失'};\nconst epistemicLabels={fact:'客观事实',inference:'分析推断',unverified:'暂时无法验证'};\n\nasync function api(path){const response=await fetch(path,{headers:{accept:'application/json'}});const body=await response.json().catch(()=>({error:{message:'响应无法读取'}}));if(!response.ok)throw new Error(body.error?.message||`HTTP ${response.status}`);return body}\nfunction setStatus(text,tone=''){const node=$('task-status');node.textContent=text;node.className=`status ${tone}`}\nfunction availabilityLabel(value){return({available:'数据可用',partial:'部分可用',unavailable:'暂不可用'})[value]||value}\n\nfunction renderDiagnosisReport(report){\n  state.report=report;\n  $('scope-list').innerHTML=report.selectedDimensions.map(item=>`<li><b>${item.priority}</b><div><strong>${esc(item.label)}</strong><p>${esc(item.relevanceReason)}</p></div><span>${availabilityLabel(item.availability)}</span></li>`).join('');\n  $('summary-text').textContent=report.summary;\n  $('limitations').innerHTML=report.limitations.length?`<strong>限制条件</strong><ul>${report.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'';\n  const topDimensions=new Set(report.selectedDimensions.slice(0,3).map(x=>x.dimension));\n  const grouped=report.selectedDimensions.slice(0,3).map(dimension=>({dimension,items:report.propositions.filter(x=>x.dimension===dimension.dimension)}));\n  $('proposition-groups').innerHTML=grouped.map(({dimension,items})=>`<section class=\"dimension-group\"><header><span>优先级 ${dimension.priority}</span><h3>${esc(dimension.label)}</h3><p>${esc(dimension.relevanceReason)}</p></header><div>${items.length?items.map(item=>`<article class=\"proposition ${item.evidenceDirection}\"><div class=\"tag-row\"><span class=\"direction ${item.evidenceDirection}\">证据方向：${directionLabels[item.evidenceDirection]}</span><span class=\"epistemic\">认知状态：${epistemicLabels[item.epistemicStatus]}</span></div><h4>${esc(item.title)}</h4><p>${esc(item.statement)}</p><button data-proposition=\"${item.id}\" aria-expanded=\"false\">查看结论依据</button></article>`).join(''):`<article class=\"proposition missing\"><div class=\"tag-row\"><span class=\"direction missing\">证据方向：缺失</span><span class=\"epistemic\">认知状态：暂时无法验证</span></div><p>该维度当前没有可验证命题。</p></article>`}</div></section>`).join('');\n  $('verification-list').innerHTML=report.verificationQuestions.map(x=>`<li>${esc(x)}</li>`).join('');\n  void topDimensions;\n}\n\nfunction openProposition(id,button){const item=state.report?.propositions.find(x=>x.id===id);if(!item)return;document.querySelectorAll('[data-proposition]').forEach(x=>x.setAttribute('aria-expanded',String(x===button)));$('drawer-content').innerHTML=`<h2 id=\"drawer-title\">${esc(item.title)}</h2><dl class=\"trace-list\"><div><dt>诊断命题</dt><dd>${esc(item.statement)}</dd></div><div><dt>证据方向</dt><dd>${directionLabels[item.evidenceDirection]}</dd></div><div><dt>认知状态</dt><dd>${epistemicLabels[item.epistemicStatus]}</dd></div><div><dt>证据引用</dt><dd>${item.evidenceRefs.map(esc).join('、')||'未取得'}</dd></div><div><dt>限制条件</dt><dd>${item.limitations.map(esc).join('；')||'无额外限制'}</dd></div></dl>`;drawer('evidence-drawer',true)}\nfunction drawer(id,open){const node=$(id);node.classList.toggle('open',open);node.setAttribute('aria-hidden',String(!open));if(open)node.querySelector('.drawer-close')?.focus();else document.querySelector('[data-proposition][aria-expanded=\"true\"]')?.focus()}\n\nasync function loadResearch(){setStatus('正在获取财务与行情数据。');try{state.bundle=await api(`/api/research?thscode=${encodeURIComponent(state.company.thscode)}`);const report=buildDiagnosisReport(state.bundle,state.company,state.question);renderDiagnosisReport(report);const partial=Object.values(state.bundle.modules||{}).some(x=>x.status!=='ok');setStatus(partial?'部分数据获取失败，相关命题已标记为缺失。':'数据已更新。',partial?'warning':'ok');$('freshness').textContent=`数据生成于 ${new Date(state.bundle.generatedAt).toLocaleString('zh-CN')}`}catch(error){console.error('research request failed',error);const empty={generatedAt:null,modules:{market:{status:'error'},financials:{status:'error'},indicators:{status:'error'}}};renderDiagnosisReport(buildDiagnosisReport(empty,state.company,state.question));setStatus('数据获取失败。页面仅显示缺失项，不生成推断。','error');$('freshness').textContent='数据获取失败'}}\nasync function searchStocks(){const query=$('stock-search').value.trim();if(!query)return;const box=$('search-results');box.hidden=false;box.textContent='正在查找';try{const result=await api(`/api/search?q=${encodeURIComponent(query)}`);box.innerHTML=result.items.map(item=>`<button data-code=\"${item.thscode}\" data-name=\"${esc(item.name||item.ticker)}\">${esc(item.name||item.ticker)} <small>${item.thscode}</small></button>`).join('')||'未找到 A 股公司'}catch(error){box.textContent=`查找失败：${error.message}`}}\n\n$('search-button').addEventListener('click',searchStocks);\n$('stock-search').addEventListener('keydown',event=>{if(event.key==='Enter')searchStocks()});\n$('search-results').addEventListener('click',event=>{const button=event.target.closest('[data-code]');if(!button)return;state.company={name:button.dataset.name,thscode:button.dataset.code};$('stock-search').value=button.dataset.name;$('search-results').hidden=true;loadResearch()});\n$('run-diagnosis').addEventListener('click',()=>{state.question=$('research-question').value.trim()||'请说明研究问题';loadResearch()});\ndocument.querySelectorAll('[data-question]').forEach(button=>button.addEventListener('click',()=>{$('research-question').value=button.dataset.question;state.question=button.dataset.question;loadResearch()}));\n$('diagnosis-map').addEventListener('click',event=>{const button=event.target.closest('[data-proposition]');if(button)openProposition(button.dataset.proposition,button)});\n$('method-button').addEventListener('click',()=>drawer('method-modal',true));\ndocument.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>drawer(button.closest('.drawer').id,false)));\ndocument.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.drawer.open').forEach(node=>drawer(node.id,false))});\nloadResearch();\n";
export const diagnosisModelScript = "const DIRECTIONS=new Set(['positive','negative','conflicting','missing']);\nconst STATUSES=new Set(['fact','inference','unverified']);\nconst DIMENSIONS=['operating_quality','financial_trend','valuation','market_characteristics','industry_position','material_events','risk'];\n\nconst n=value=>value===null||value===undefined||value===''||!Number.isFinite(Number(value))?null:Number(value);\nconst pct=value=>n(value)===null?'未取得':`${n(value)>=0?'+':''}${n(value).toFixed(1)}%`;\nconst valuesFrom=bundle=>Object.fromEntries((bundle?.modules?.indicators?.data?.abilities||[]).flatMap(group=>(group.indicators||[]).map(item=>[item.index_id,n(item.value)])));\nconst pick=(values,...keys)=>{for(const key of keys)if(values[key]!==undefined)return values[key];return null};\n\nfunction intentOf(question=''){\n  if(/能买吗|买不买|会涨|涨不涨|目标价|卖出/.test(question))return'investment_boundary';\n  if(/估值|贵不贵|便宜|市盈率|市净率|同行/.test(question))return'valuation';\n  if(/现金流|回款|负债|偿债|杠杆|债务/.test(question))return'cash_debt';\n  return'growth';\n}\n\nconst dimensionLabels={operating_quality:'经营质量',financial_trend:'财务趋势',valuation:'估值',market_characteristics:'行情特征',industry_position:'行业位置',material_events:'重要事件',risk:'风险'};\nconst dimensionOrders={\n  growth:['operating_quality','financial_trend','industry_position','material_events','risk','valuation','market_characteristics'],\n  cash_debt:['financial_trend','risk','operating_quality','industry_position','material_events','valuation','market_characteristics'],\n  valuation:['valuation','industry_position','financial_trend','risk','market_characteristics','operating_quality','material_events'],\n  investment_boundary:['operating_quality','financial_trend','valuation','risk','industry_position','material_events','market_characteristics'],\n};\nconst reasons={\n  growth:{operating_quality:'问题涉及增长是否形成经营成果',financial_trend:'需要核对收入、利润与现金的变化关系',industry_position:'需要区分公司变化与行业共同变化'},\n  cash_debt:{financial_trend:'问题直接涉及现金与负债变化',risk:'需要核对偿债与资金压力',operating_quality:'现金占用可能来自经营环节'},\n  valuation:{valuation:'问题直接涉及当前估值',industry_position:'估值需要同口径同行参照',financial_trend:'增长与盈利趋势影响估值解释'},\n  investment_boundary:{operating_quality:'只呈现可验证经营事实',financial_trend:'只呈现可验证财务变化',valuation:'买卖判断需要估值证据'},\n};\n\nfunction selectedDimensions(intent,bundle){\n  const order=dimensionOrders[intent]||dimensionOrders.growth;\n  return order.map((dimension,index)=>({\n    dimension,label:dimensionLabels[dimension],priority:index+1,\n    relevanceReason:reasons[intent]?.[dimension]||'作为补充诊断维度保留',\n    availability:['valuation','industry_position','material_events'].includes(dimension)?'unavailable':bundle?.modules?'partial':'unavailable',\n  }));\n}\n\nfunction proposition(input){\n  if(!DIRECTIONS.has(input.evidenceDirection)||!STATUSES.has(input.epistemicStatus))throw new Error('invalid proposition state');\n  return {evidenceRefs:[],limitations:[],...input};\n}\n\nexport function buildDiagnosisReport(bundle,company,question=''){\n  const intent=intentOf(question);\n  const companyType=company?.companyType||'general_corporate';\n  const limitations=companyType==='general_corporate'?['公司类型待验证，当前使用通用公司诊断顺序。']:[];\n  const values=valuesFrom(bundle);\n  const revenue=pick(values,'calculate_operating_income_yoy_growth_ratio','operating_income_yoy_growth_ratio');\n  const profit=pick(values,'calculate_parent_holder_net_profit_yoy_growth_ratio','net_profit_yoy_growth_ratio');\n  const cash=pick(values,'net_profit_cash_content');\n  const debt=pick(values,'assets_debt_ratio');\n  const growthKnown=revenue!==null&&profit!==null;\n  const propositions=[];\n\n  if(growthKnown){\n    const direction=revenue>=0&&profit>=0?'positive':revenue*profit<0?'conflicting':'negative';\n    propositions.push(proposition({id:'growth-fact',dimension:'operating_quality',title:'收入与利润的变化方向',statement:`营业收入同比 ${pct(revenue)}，归母净利润同比 ${pct(profit)}。`,evidenceDirection:direction,epistemicStatus:'fact',evidenceRefs:['metric-revenue-growth','metric-profit-growth']}));\n    propositions.push(proposition({id:'growth-inference',dimension:'operating_quality',title:'增长关系的分析解释',statement:revenue*profit<0?'收入与利润方向不一致，增长结构需要进一步核对。':profit<revenue?'利润增速低于收入增速，需要核对成本与费用变化。':'收入与利润方向一致，但仍需同行数据确认相对位置。',evidenceDirection:direction,epistemicStatus:'inference',evidenceRefs:['growth-fact'],limitations:['未取得同口径同行增速']}));\n  }else propositions.push(proposition({id:'growth-missing',dimension:'operating_quality',title:'收入与利润变化',statement:'最新收入或利润增速未完整取得。',evidenceDirection:'missing',epistemicStatus:'unverified',limitations:['指标模块缺失或获取失败']}));\n\n  if(cash!==null)propositions.push(proposition({id:'cash-fact',dimension:'financial_trend',title:'利润与经营现金的对应关系',statement:`每 100 元利润对应约 ${cash.toFixed(0)} 元经营现金。`,evidenceDirection:cash>=100?'positive':'negative',epistemicStatus:'fact',evidenceRefs:['metric-cash-content']}));\n  else propositions.push(proposition({id:'cash-missing',dimension:'financial_trend',title:'利润与经营现金的对应关系',statement:'经营现金与利润的同口径数据未取得。',evidenceDirection:'missing',epistemicStatus:'unverified',limitations:['现金质量指标缺失']}));\n  if(debt!==null)propositions.push(proposition({id:'debt-fact',dimension:'risk',title:'资产负债关系',statement:`每 100 元资产中约有 ${debt.toFixed(1)} 元负债。`,evidenceDirection:debt>70?'negative':'positive',epistemicStatus:'fact',evidenceRefs:['metric-debt-ratio'],limitations:['资产负债率不区分经营性负债与有息负债']}));\n\n  propositions.push(proposition({id:'industry-unverified',dimension:'industry_position',title:'同行位置',statement:'同日、同口径的同行数据尚未取得。',evidenceDirection:'missing',epistemicStatus:'unverified',limitations:['缺少可比公司样本与比较日期']}));\n  propositions.push(proposition({id:'valuation-unverified',dimension:'valuation',title:'估值位置',statement:'同日估值与历史分位尚未取得。',evidenceDirection:'missing',epistemicStatus:'unverified',limitations:['不能使用过期价格替代当前估值']}));\n\n  const summary=intent==='investment_boundary'\n    ?'本产品不提供买卖建议，也不能预测确定性涨跌；以下仅整理可验证的经营、财务与估值证据。'\n    :growthKnown?`已确认收入同比 ${pct(revenue)}、归母净利润同比 ${pct(profit)}；同行、估值与事件证据仍需补充。`:'关键财务证据未完整取得，当前只展示可验证内容和缺失项。';\n  const dates=[...(bundle?.modules?.financials?.income||[]),...(bundle?.modules?.financials?.balance||[]),...(bundle?.modules?.financials?.cashflow||[])].map(x=>n(x.period_end_ms||x.period_end||x.end_date_ms)).filter(x=>x!==null);\n  return {\n    company,companyType,intent,question,\n    asOf:{generatedAt:bundle?.generatedAt||null,financialPeriod:dates.length?new Date(Math.max(...dates)).toISOString().slice(0,10):null},\n    selectedDimensions:selectedDimensions(intent,bundle),summary,propositions,\n    verificationQuestions:['补充同口径同行增速后确认相对位置','核对最新公告中是否存在一次性影响','取得同日估值与历史分位'],\n    limitations,\n  };\n}\n\nexport { DIMENSIONS };\n";
